def apply_discounts(price_cents, codes):
    # Start with the original price
    price = price_cents

    # Apply at most one percentage discount, the largest one first
    largest_pct = None
    for code in codes:
        if code.startswith("PCT"):
            num = int(code[3:])
            if largest_pct is None or num > largest_pct:
                largest_pct = num

    if largest_pct is not None:
        discount = (largest_pct / 100) * price
        price -= int(discount)  # Round down to whole cent

    # Subtract all FLAT discounts in the order they appear
    for code in codes:
        if code.startswith("FLAT"):
            num = int(code[4:])
            price -= num

    # The final price is never below 0
    if price < 0:
        price = 0

    return price
```

