def is_valid_coupon(code):
    # Check if the code has the correct format "XXXX-XXXX-XXXX"
    if not code.startswith("XXXX-XXXX-XXXX"):
        return False

    # Split the code into three groups of 4 characters
    parts = code.split("-")
    if len(parts) != 3:
        return False

    # Check if each part has exactly 4 characters
    for part in parts:
        if len(part) != 4:
            return False

    # Check if all characters are from the allowed alphabet
    alphabet = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"
    for part in parts:
        for char in part:
            if char not in alphabet:
                return False

    # Calculate the check character
    # Take the first 11 characters (excluding the last one)
    first_11 = code[:11]
    total = 0
    for char in first_11:
        # Get the value of the character (0 for '2', 1 for '3', ..., 31 for 'Z')
        value = ord(char) - ord('2')
        total += value

    # Calculate the check character
    check_value = total % 32
    check_char = ""
    for i in range(32):
        if i == 0:
            check_char = "2"
        elif i == 1:
            check_char = "3"
        else:
            check_char = chr(ord('2') + i)
    # The last character of the code should be the check character
    last_char = code[-1]
    if check_char != last_char:
        return False

    return True
```

